INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(37811, 'Nehemiah 12:42', 'Nehemiah', 12, 42, 'معسیا، شمعیه، العازار، عزي، یوحانان، ملکیا، عیلام او ایصر د هغوی پسې روان وو. هغو سندرغاړو چې د یزرحیا له خوا یې لارښوونه کېدله، په لوړ اواز سره سندرې ویلې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah12_verse_42.mp3', '', 1761754199, 1761754199),
(37812, 'Nehemiah 12:43', 'Nehemiah', 12, 43, 'په هغه ورځ ډېرې قربانۍ وړاندې شوې او خلک د خپلو ښځو او ماشومانو سره خوشحاله وو، ځکه چې خدای د هغوی زړونه د خوشحالۍ څخه ډک کړي وو. د اورشلیم د خلکو د خوشحالۍ اواز له ډېر لېرې ځای څخه اورېدل کېده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah12_verse_43.mp3', '', 1761754199, 1761754199),
(37813, 'Nehemiah 12:44', 'Nehemiah', 12, 44, 'په هغه ورځ ځینې خلک د ګودامونو د مسوولانو په توګه وټاکل شول چې په هغو کې به د خدای د کور دپاره اعانې، د حاصلاتو لسمه برخه او لومړنۍ غلې دانې او مېوې چې هر کال به پخېدلې، ساتل کېدلې. دې مسوولانو دا دنده درلودله چې د هغو کروندو څخه چې ښارونو ته نژدې وې، د کاهنانو او لاویانو برخه د شریعت د اصولو سره سم راټوله کړي. د یهودا ټول خلک د کاهنانو او لاویانو د خدمت څخه خوشحاله وو،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah12_verse_44.mp3', '', 1761754199, 1761754199),
(37814, 'Nehemiah 12:45', 'Nehemiah', 12, 45, 'ځکه چې هغوی د پاکوالي مراسم او هغه نورې دندې سرته رسولې چې خدای د هغو حکم کړی ؤ. د خدای د کور سندرغاړو او ساتونکو هم خپلې دندې د داود پاچا او د هغه د زوی سلیمان د حکم سره سم تر سره کولې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah12_verse_45.mp3', '', 1761754199, 1761754199),
(37815, 'Nehemiah 12:46', 'Nehemiah', 12, 46, 'په پخوا زمانه کې، یعنې د داود او اساف په زمانه کې د سندرغاړو او خدای ته د شکرګزارۍ او ثنا ویلو د سندرو دپاره لارښوونکي موجود وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah12_verse_46.mp3', '', 1761754199, 1761754199),
(37816, 'Nehemiah 12:47', 'Nehemiah', 12, 47, 'د زروبابل او نحمیا په زمانه کې به د اسراییلو ټولو خلکو هره ورځ د خدای د کور سندرغاړو او ساتونکو ته خواړه او نور د اړتیا وړ شیان ورکول. خلکو به لاویانو ته سپېڅلې نذرانې ورکولې او لاویانو به کاهنانو ته د اړتیا وړ برخه ورکوله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah12_verse_47.mp3', '', 1761754199, 1761754199),
(37817, 'Lamentations 5:1', 'Lamentations', 5, 1, 'اے مالِکه خُدايه، راياد کړه چې په مونږ څۀ وشو، وګوره چې زمونږ څنګه بې‌عزتى شوې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations5_verse_1.mp3', '', 1761754199, 1761754199),
(37818, 'Lamentations 5:2', 'Lamentations', 5, 2, 'زمونږ ميراث غېرو ته حواله شوے دے او زمونږ کورونه پردو خلقو قبضه کړى دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations5_verse_2.mp3', '', 1761754199, 1761754199),
(37819, 'Lamentations 5:3', 'Lamentations', 5, 3, 'مونږ يتيمان او بې‌پلاره شوى يُو او زمونږ ميندې کونډې شوې دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations5_verse_3.mp3', '', 1761754199, 1761754199),
(37820, 'Lamentations 5:4', 'Lamentations', 5, 4, 'مونږ د څښلو اوبۀ او د سوزولو خشاک په بيعه اخلو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations5_verse_4.mp3', '', 1761754199, 1761754199),
(37821, 'Lamentations 5:5', 'Lamentations', 5, 5, 'هغوئ څوک چې مونږ پسې وُو راته په سر ناست دى او مونږ ډېر ستومانه شُو خو هيڅ آرام ته مو نۀ پرېږدى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations5_verse_5.mp3', '', 1761754199, 1761754199),
(37822, 'Lamentations 5:6', 'Lamentations', 5, 6, 'مونږ خپل ځان مِصر او اسور ته حواله کړو چې مونږ ته پوره روټۍ مِلاو شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations5_verse_6.mp3', '', 1761754199, 1761754199),
(37823, 'Lamentations 5:7', 'Lamentations', 5, 7, 'زمونږ پلار نيکۀ ګناه وکړه خو هغوئ مړۀ دى او اوس مونږ د هغوئ د ګناه سزا خورو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations5_verse_7.mp3', '', 1761754199, 1761754199),
(37824, 'Lamentations 5:8', 'Lamentations', 5, 8, 'غلامان په مونږ حکومت کوى او هيڅ څوک نشته چې مونږ د هغوئ د لاس نه آزاد کړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations5_verse_8.mp3', '', 1761754199, 1761754199),
(37825, 'Lamentations 5:9', 'Lamentations', 5, 9, 'مونږ د روټۍ پېدا کولو دپاره خپل ځان په خطره کښې اچولے دے ځکه چې په ټوله علاقه کښې وسله وال ګرځى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations5_verse_9.mp3', '', 1761754199, 1761754199),
(37826, 'Lamentations 5:10', 'Lamentations', 5, 10, 'زمونږ څرمن لکه د تنور په شان ګرمه ده، د قحط د ډېر تاو نه سوزېدلې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations5_verse_10.mp3', '', 1761754199, 1761754199),
(37827, 'Lamentations 5:11', 'Lamentations', 5, 11, 'په صيون کښې د ښځو عزت لوټ شوے دے او د يهوداه په ښارونو کښې د پېغلو عزت لوټ شوے دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations5_verse_11.mp3', '', 1761754199, 1761754199),
(37828, 'Lamentations 5:12', 'Lamentations', 5, 12, 'دوئ شهزادګان د لاسونو نه راځوړند کړى دى او د مشرانو بې‌عزتى يې کړې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations5_verse_12.mp3', '', 1761754199, 1761754199),
(37829, 'Lamentations 5:13', 'Lamentations', 5, 13, 'په ځوانانو په زور مېچنې ګرځولے شى، او زلمى د لرګو د درنو بارونو لاندې په تکليف روان دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations5_verse_13.mp3', '', 1761754199, 1761754199),
(37830, 'Lamentations 5:14', 'Lamentations', 5, 14, 'مشرانو د ښار په دروازه د جرګو ځايونه پرېښودل او ځوانانو خپل ساز و سرود پرېښودو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations5_verse_14.mp3', '', 1761754199, 1761754199),
(37831, 'Lamentations 5:15', 'Lamentations', 5, 15, 'زمونږ د زړۀ خوشحالى رانه اخستے شوې ده او زمونږ ګډا په ماتم بدله شوې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations5_verse_15.mp3', '', 1761754199, 1761754199),
(37832, 'Lamentations 5:16', 'Lamentations', 5, 16, 'زمونږ نه تاج و تخت اخستلے شوے دے، افسوس په مونږ ځکه چې مونږ ګناه کړې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations5_verse_16.mp3', '', 1761754199, 1761754199),
(37833, 'Lamentations 5:17', 'Lamentations', 5, 17, 'ځکه د دې په وجه زمونږ زړونه مات شوى دى او د ژړا په وجه زمونږ نظر کم شوے دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations5_verse_17.mp3', '', 1761754199, 1761754199),
(37834, 'Lamentations 5:18', 'Lamentations', 5, 18, 'دا چې د صيون غر وران ويجاړ پروت دے او ګيدړان په کښې اوسيږى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations5_verse_18.mp3', '', 1761754199, 1761754199),
(37835, 'Lamentations 5:19', 'Lamentations', 5, 19, 'خو تۀ اے مالِکه خُدايه، د تل دپاره حکومت کوې او ستا تخت په ټولو نسلونو کښې قائم پاتې کيږى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations5_verse_19.mp3', '', 1761754199, 1761754199),
(37836, 'Lamentations 5:20', 'Lamentations', 5, 20, 'تا ولې مونږ بلکل هېر کړى يُو؟ تا ولې مونږ ډېرو ورځو نه پرېښى يُو؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations5_verse_20.mp3', '', 1761754199, 1761754199),
(37837, 'Lamentations 5:21', 'Lamentations', 5, 21, 'اے مالِکه خُدايه مونږ ځان ته راوبله، مونږ بحال کړه او زمونږ حال د مخکښې په شان کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations5_verse_21.mp3', '', 1761754199, 1761754199),
(37838, 'Lamentations 5:22', 'Lamentations', 5, 22, 'ولې تا مونږ تل دپاره رد کړى يُو؟ او تۀ مونږ ته د حد نه زيات غصه يې؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations5_verse_22.mp3', '', 1761754199, 1761754199),
(37839, 'Ezekiel 7:1', 'Ezekiel', 7, 1, 'څښتن ماته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel7_verse_1.mp3', '', 1761754199, 1761754199),
(37840, 'Ezekiel 7:2', 'Ezekiel', 7, 2, '«ای فاني انسانه، زه څښتن تعالی د اسراییلو خلکو ته داسې وایم چې دا ستاسو دپاره د پای ټکی دی! ستاسو د ټول هېواد د پای وخت رارسېدلی دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel7_verse_2.mp3', '', 1761754199, 1761754199),
(37841, 'Ezekiel 7:3', 'Ezekiel', 7, 3, 'نو اوس ستاسو دپاره د پای وخت رارسېدلی دی او خپل غضب به په تاسو باندې نازل کړم. تاسو به د خپلو اوسېدونکو د بدو کړنو له امله محاکمه او د هغوی د ټولو د کرکې وړ عملونو له امله به تاسو ته سزا درکړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel7_verse_3.mp3', '', 1761754199, 1761754199),
(37842, 'Ezekiel 7:4', 'Ezekiel', 7, 4, 'زه به تاسو ته د مینې په سترګه ونه ګورم او په تاسو باندې به هېڅ رحم ونه کړم. زه به تاسو ته د هغو د کرکې وړ عملونو له امله چې کړي مو دي، سزا درکړم. نو بیا به تاسو په دې پوه شئ چې زه څښتن یم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel7_verse_4.mp3', '', 1761754199, 1761754199),
(37843, 'Ezekiel 7:5', 'Ezekiel', 7, 5, '«زه څښتن تعالی داسې وایم: ‹په تاسو به یو مصیبت راشي. ګوره، داسې مصیبت چې هېڅکله په تاسو نه وي راغلی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel7_verse_5.mp3', '', 1761754199, 1761754199),
(37844, 'Ezekiel 7:6', 'Ezekiel', 7, 6, 'اخري وخت رارسېدلی دی. اخري وخت ډېر نژدې دی او ټول شیان پای ته رسیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel7_verse_6.mp3', '', 1761754199, 1761754199),
(37845, 'Ezekiel 7:7', 'Ezekiel', 7, 7, 'ای د دې هېواد اوسېدونکو، ستاسو د اجل وخت رارسېدلی دی. هغه وخت رانژدې دی چې نور به په غرونو کې د خوشحالۍ اواز وانه ورېدل شي، بلکې تاسو به په پرېشانۍ کې یئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel7_verse_7.mp3', '', 1761754199, 1761754199),
(37846, 'Ezekiel 7:8', 'Ezekiel', 7, 8, 'ډېر زر به په تاسو باندې خپل قهر او غضب نازل کړم. زه به تاسو د خپلو بدو کړنو له امله محاکمه او د خپلو ټولو د کرکې وړ عملونو له امله به سزا درکړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel7_verse_8.mp3', '', 1761754199, 1761754199),
(37847, 'Ezekiel 7:9', 'Ezekiel', 7, 9, 'زه به تاسو ته د مینې په سترګه ونه ګورم او په تاسو باندې به هېڅ رحم ونه کړم. زه به تاسو ته د هغو کرکې وړ عملونو له امله چې تاسو کړي دي، سزا درکړم. نو بیا به تاسو په دې پوه شئ چې زه هغه څښتن یم چې تاسو ته سزا درکوم.›»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel7_verse_9.mp3', '', 1761754199, 1761754199),
(37848, 'Ezekiel 7:10', 'Ezekiel', 7, 10, 'څښتن بیا وویل: «ګورئ، په اسراییلو باندې د مصیبت ورځ ډېره نژدې ده. ستاسو اجل رارسېدلی دی. ظلم او زیاتی خپل وروستي حد ته رسېدلی دی او غرور زیات شوی دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel7_verse_10.mp3', '', 1761754199, 1761754199),
(37849, 'Ezekiel 7:11', 'Ezekiel', 7, 11, 'د ظلم او زیاتي له امله شرارت زیات شوی دی. د دې مغرورو او بدکاره خلکو نه به هېڅ شی پاتې نه شي، نه به د هغوی شتمني او نه به د هغوی شان او شوکت.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel7_verse_11.mp3', '', 1761754199, 1761754199),
(37850, 'Ezekiel 7:12', 'Ezekiel', 7, 12, 'هغه وخت رارسېدلی دی او هغه ورځ نژدې شوې ده. په هغه ورځ دې اخیستونکي خوشحالي نه کوي او خرڅوونکي دې خفګان نه کوي، ځکه ټول خلک به زما په قهر او غضب اخته شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel7_verse_12.mp3', '', 1761754199, 1761754199),
(37851, 'Ezekiel 7:13', 'Ezekiel', 7, 13, 'ترڅو چې اخیستونکی او خرڅوونکی ژوندي وي، اخیستونکی به بېرته خپل جایداد تر‌لاسه نه کړي، ځکه دا رویا چې زه یې تاسو ته بیانوم، په ټولو پورې اړه لري او هغه بدلېدونکې نه ده. د ګناهونو له امله به هېڅوک ژوندی پاتې نه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel7_verse_13.mp3', '', 1761754199, 1761754199),
(37852, 'Ezekiel 7:14', 'Ezekiel', 7, 14, 'د جګړې سرنی وهل شوی دی او هرڅه تیار دي، خو هېڅوک جګړې ته نه ځي، ځکه چې په ټولو خلکو باندې زما غضب نازل شوی دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel7_verse_14.mp3', '', 1761754199, 1761754199),
(37853, 'Ezekiel 7:15', 'Ezekiel', 7, 15, 'د ښار څخه دباندې جنګ او په ښار کې به وبا او قحطي وي. هرڅوک چې د ښار نه دباندې ووځي، په توره به ووژل شي او هغه څوک چې په ښار کې پاتې شي د قحطۍ او وبا له امله به مړه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel7_verse_15.mp3', '', 1761754199, 1761754199),
(37854, 'Ezekiel 7:16', 'Ezekiel', 7, 16, 'حتی که څوک ژوندي هم پاتې شي، د درو د کوترو په شان به غرونو ته وتښتي او هلته به هم د خپلو ګناهونو له امله زګېروی وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel7_verse_16.mp3', '', 1761754199, 1761754199),
(37855, 'Ezekiel 7:17', 'Ezekiel', 7, 17, 'د هرچا لاسونه به کمزوري شي او زنګنونه به یې رپیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel7_verse_17.mp3', '', 1761754199, 1761754199),
(37856, 'Ezekiel 7:18', 'Ezekiel', 7, 18, 'هغوی ټول به په سخته وېره کې د ویر کالي واغوندي. د هغوی سرونه به د ویر له امله خریلي وي او له شرمه به یې سرونه ټیټ وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel7_verse_18.mp3', '', 1761754199, 1761754199),
(37857, 'Ezekiel 7:19', 'Ezekiel', 7, 19, 'هغوی به خپل سپین زر لکه د چټلیو په شان په کوڅو کې وغورځوي او د هغوی سره زر به یو ناپاکه شی وګڼل شي، ځکه کله چې څښتن خپل غضب نازل کړي، نو نه سپین او نه سره زر هغوی ژغورلی شي. هغوی په دې باندې خپله لوږه نه شي ختمولی او نه ورباندې د هغوی خېټې مړیږي. ځکه چې سپین او سره زر هغوی د ګناه خواته بوتلل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel7_verse_19.mp3', '', 1761754199, 1761754199),
(37858, 'Ezekiel 7:20', 'Ezekiel', 7, 20, 'یو وخت هغوی په خپلو ښکلو زېوراتو باندې ویاړ کاوه، خو له هغو نه یې د کرکې وړ بتانو په جوړولو کې کار اخیست. نو له دې امله به زه دا ټوله شتمني د هغوی دپاره ناپاکه وګرځوم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel7_verse_20.mp3', '', 1761754199, 1761754199),
(37859, 'Ezekiel 7:21', 'Ezekiel', 7, 21, 'څښتن بیا وویل: «زه به پردي خلک پرېږدم چې هغوی لوټ کړي او د نړۍ شریر خلک به د هغوی شتمني یوسي او هغه به یو عادي شی جوړ کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel7_verse_21.mp3', '', 1761754199, 1761754199),
(37860, 'Ezekiel 7:22', 'Ezekiel', 7, 22, 'زه به خپل مخ د دې شریرو خلکو څخه واړوم او هغوی به زما قیمتي ځای ته سپکاوی وکړي. لوټماران به هلته ورننوځي او هغه به یو عادي شی جوړ کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel7_verse_22.mp3', '', 1761754199, 1761754199),
(37861, 'Ezekiel 7:23', 'Ezekiel', 7, 23, 'د اسراییلو د قوم دپاره زنځیرونه تیار کړئ، ځکه د هغوی ټول هېواد د وینو تویولو او جنایتونو څخه ډک دی او ښار هم د تاوتریخوالي څخه ډک دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel7_verse_23.mp3', '', 1761754199, 1761754199),
(37862, 'Ezekiel 7:24', 'Ezekiel', 7, 24, 'زه به تر ټولو شریر قومونه دلته راولم چې د هغوی کورونه په زور ونیسي. زه به د زورورو خلکو غرور پای ته ورسوم او زه به پرېږدم چې د هغوی سپېڅلي ځایونو ته سپکاوی وشي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel7_verse_24.mp3', '', 1761754199, 1761754199),
(37863, 'Ezekiel 7:25', 'Ezekiel', 7, 25, 'کله چې هغوی په سخته وېره اخته شي، نو د امن او ارامۍ په لټه کې به شي، خو هغه به هېڅکله ونه مومي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel7_verse_25.mp3', '', 1761754199, 1761754199),
(37864, 'Ezekiel 7:26', 'Ezekiel', 7, 26, 'یو مصیبت پسې به بل مصیبت راشي او یوازې ګونګوسې به اورېدل کیږي. هغوی به د پیغمبرانو څخه د راتلونکې په اړه د رویا غوښتنه کوي. د کاهنانو تعلیم به پای ته ورسیږي او مشران به د مشورې ورکولو څخه عاجز وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel7_verse_26.mp3', '', 1761754199, 1761754199),
(37865, 'Ezekiel 7:27', 'Ezekiel', 7, 27, 'پاچا به ویر کوي، مامورین به خپله هیله له لاسه ورکړي او خلک به له وېرې څخه رپیږي. هغوی چې کوم کارونه کړي دي، د هغو سره سم به زه هغوی ته سزا ورکړم او د هغوی په اړه به داسې قضاوت وکړم لکه څنکه چې هغوی د نورو په هکله کړی دی. نو بیا به هغوی پوه شي چې زه څښتن یم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel7_verse_27.mp3', '', 1761754199, 1761754199),
(37866, 'Ecclesiastes 5:1', 'Ecclesiastes', 5, 1, 'کله چې د خدای کور ته ځې نو په خپلو قدمونو پام کوه. هلته د اورېدلو دپاره تلل، له هغه قربانۍ څخه ښه ده چې د کم‌عقلانو له خوا وړاندې کیږي. ځکه هغوی په دې نه پوهیږي چې کوم کار تر‌سره کوي، هغه بد دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes5_verse_1.mp3', '', 1761754199, 1761754199),
(37867, 'Ecclesiastes 5:2', 'Ecclesiastes', 5, 2, 'په خپلو خبرو کې بیړه مه کوه او د خپل زړه خبرې پرته له غور څخه خدای ته مه بیانوه، ځکه خدای اسمان کې دی او ته په ځمکه باندې یې. نو له همدې امله پرېږده چې ستا خبرې لنډې وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes5_verse_2.mp3', '', 1761754199, 1761754199),
(37868, 'Ecclesiastes 5:3', 'Ecclesiastes', 5, 3, 'نو څومره چې ډېر پرېشانه خیالونه ولرې هغومره خراب خوبونه ګورې او څومره چې ډېرې خبرې کوې هغومره خپل کم‌عقلتوب ښکاره کوې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes5_verse_3.mp3', '', 1761754199, 1761754199),
(37869, 'Ecclesiastes 5:4', 'Ecclesiastes', 5, 4, 'کله چې خدای ته یو نذر ومنې نو هغه بې له ځنډه ورکړه. خدای له کم‌عقلانو نه خوشحاله نه دی. کوم نذر دې چې منلی دی هغه ورکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes5_verse_4.mp3', '', 1761754199, 1761754199),
(37870, 'Ecclesiastes 5:5', 'Ecclesiastes', 5, 5, 'دا ښه ده چې یو نذر ونه منې، له هغې نه چې ویې منې خو ور یې نه کړې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes5_verse_5.mp3', '', 1761754199, 1761754199),
(37871, 'Ecclesiastes 5:6', 'Ecclesiastes', 5, 6, 'مه پرېږده چې ستا د خولې خبرې تا د ګناه په لور یوسي او د کاهن په وړاندې مه وایه چې تا نه غلطي شوې ده، هسې نه چې خدای ستا په خبرو باندې په غوسه شي او په خپلو لاسونو تر‌سره شوي کارونه دې تباه کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes5_verse_6.mp3', '', 1761754199, 1761754199),
(37872, 'Ecclesiastes 5:7', 'Ecclesiastes', 5, 7, 'په رښتیا چې کله خوبونه او خیالونه ډېر شي نو د لوګي او پوکي په شان خبرې هم ډېرې شي خو ته له خدای څخه وېره کوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes5_verse_7.mp3', '', 1761754199, 1761754199),
(37873, 'Ecclesiastes 5:8', 'Ecclesiastes', 5, 8, 'که چېرې ته په کوم ولایت کې ګورې چې په غریبانو باندې ظلم کیږي او انصاف او صداقت تر پښو لاندې کیږي، نو په دې خبره مه حیرانېږه. ځکه هر مامور د لوړ‌پوړي چارواکي له خوا څارل کیږي او حتی د هغه په سر هم لوړ‌پوړی چارواکی شته.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes5_verse_8.mp3', '', 1761754199, 1761754199),
(37874, 'Ecclesiastes 5:9', 'Ecclesiastes', 5, 9, 'نو د یو هېواد ګټه په دې کې ده چې پاچا په ټولو باندې واکمن وي او ټولې ځمکې وڅاري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes5_verse_9.mp3', '', 1761754199, 1761754199),
(37875, 'Ecclesiastes 5:10', 'Ecclesiastes', 5, 10, 'څوک چې له پیسو سره مینه لري هغه به هېڅکله هم په پیسو موړ نه شي او څوک چې په مال او دولت مین وي هغه به په خپلو حاصلاتو موړ نه شي نو دا حالت هم لوګی او پوکی دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes5_verse_10.mp3', '', 1761754199, 1761754199),
(37876, 'Ecclesiastes 5:11', 'Ecclesiastes', 5, 11, 'څومره چې نعمتونه زیاتیږي هغومره د هغه خوړونکي هم زیاتیږي نو پرته له تشو کتلو، د هغه د خاوند ګټه څه ده؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes5_verse_11.mp3', '', 1761754199, 1761754199),
(37877, 'Ecclesiastes 5:12', 'Ecclesiastes', 5, 12, 'د یو مزدور خوب خوږ وي، که هغه ډېره خوري یا لږه خو د شتمن سړي مړه ګېډه هغه خوب ته نه پرېږدي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes5_verse_12.mp3', '', 1761754199, 1761754199),
(37878, 'Ecclesiastes 5:13', 'Ecclesiastes', 5, 13, 'ما د اسمان لاندې بله لویه بدبختي هم ولیدله. هغه دا وه چې یو سړي د ځان دپاره شتمني ټولوله چې د هغه د تاوان سبب ګرځېده،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes5_verse_13.mp3', '', 1761754199, 1761754199),
(37879, 'Ecclesiastes 5:14', 'Ecclesiastes', 5, 14, 'او وروسته بیا هغه دغه ټوله شتمني د بدې پېښې له امله له لاسه ورکړه. که څه هم هغه یو زوی درلود خو هغه یې تش لاس پرېښود.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes5_verse_14.mp3', '', 1761754199, 1761754199),
(37880, 'Ecclesiastes 5:15', 'Ecclesiastes', 5, 15, 'نو دا سړی لکه څنګه چې د خپلې مور له ګېډې څخه لوڅ او تش لاس نړۍ ته راغلی ؤ هماغسې به له دې نړۍ څخه لوڅ او تش لاس بېرته ځي، او څه چې یې د خپل زیار او زحمت له امله ټول کړي دي، هغه به له ځان سره نه وړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes5_verse_15.mp3', '', 1761754199, 1761754199),
(37881, 'Ecclesiastes 5:16', 'Ecclesiastes', 5, 16, 'دا هم لویه بدبختي ده لکه څنګه چې نړۍ ته راغلی دی هماغسې له نړۍ نه به بېرته ځي، او هغه ګټه چې په زیار او زحمت یې تر‌لاسه کوي، هغه په باد پسې منډې وهل دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes5_verse_16.mp3', '', 1761754199, 1761754199),
(37882, 'Ecclesiastes 5:17', 'Ecclesiastes', 5, 17, 'بله دا چې هغه د خپل ژوند ټولې ورځې په تیارې او ناروغۍ او په غوسه او غضب کې تېروي او خپل ځان خوري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes5_verse_17.mp3', '', 1761754199, 1761754199),
(37883, 'Ecclesiastes 5:18', 'Ecclesiastes', 5, 18, 'نو وګوره، ماته معلومه شوه چې څومره سمه او مناسبه ده چې انسان د خپل ژوند په لنډه موده کې چې خدای ورته ورکړې ده، وخوري، وڅښي او د خپل زیار او زحمت نه چې د اسمان لاندې یې وباسي، خوند واخلي ځکه چې دا د هغه برخه ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes5_verse_18.mp3', '', 1761754199, 1761754199),
(37884, 'Ecclesiastes 5:19', 'Ecclesiastes', 5, 19, 'همدا شان، کله چې خدای هرچا ته مال او دولت ورکړي، او ورسره دا قدرت هم ورکړي چې له هغه نه وخوري او خپله برخه تر‌لاسه کړي او د خپل زیار او زحمت نه خوشحاله اوسي، نو دا د خدای له خوا یو انعام دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes5_verse_19.mp3', '', 1761754199, 1761754199),
(37885, 'Ecclesiastes 5:20', 'Ecclesiastes', 5, 20, 'په حقیقت کې، هغه د خپل ژوند په ورځو باندې فکر نه کوي ځکه خدای هغه په خوشحالیو کې دومره بوخت ساتي چې د اندېښنو دپاره وخت نه لري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes5_verse_20.mp3', '', 1761754199, 1761754199),
(37886, 'Zechariah 11:1', 'Zechariah', 11, 1, 'خپلې دروازې کولاو کړه، اے لبنانه، چې اور ستا د دِيار ونې وسوزوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah11_verse_1.mp3', '', 1761754199, 1761754199),
(37887, 'Zechariah 11:2', 'Zechariah', 11, 2, 'فرياد وکړه، اے د نختر ونې، ځکه چې د دِيار ونې راغورزېدلې دى، هغه د شان او شوکت والا ونې تباه شوې دى. فرياد وکړئ، اے د بسن د څېړو ونو، ګڼ ځنګلونه هم ختم شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah11_verse_2.mp3', '', 1761754199, 1761754199),
(37888, 'Zechariah 11:3', 'Zechariah', 11, 3, 'د قوم شپونکو فرياد ته غوږ ونيسئ، د هغوئ د څرن شنۀ ځايونه تباه شول. د زمرو غړمبار ته غوږ ونيسئ، د اُردن ګڼ ځنګلونه تباه شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah11_verse_3.mp3', '', 1761754199, 1761754199),
(37889, 'Zechariah 11:4', 'Zechariah', 11, 4, 'مالِک خُدائ زما خُدائ پاک دا فرمائى، ”هغه ګډې وڅروه چې د حلالې دپاره نښه شوې دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah11_verse_4.mp3', '', 1761754199, 1761754199),
(37890, 'Zechariah 11:5', 'Zechariah', 11, 5, 'د دې اخستونکى دا حلالې کړى او سزا ورته مِلاو نۀ شى. چې څوک يې خرڅوى هغوئ وائى، د مالِک خُدائ ثناء صِفت دې وى، مونږ مالداره شُو. د دې خپل شپونکى په دې رحم نۀ کوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah11_verse_5.mp3', '', 1761754199, 1761754199),
(37891, 'Zechariah 11:6', 'Zechariah', 11, 6, 'نو زۀ به هم نور د دې مُلک په خلقو رحم ونۀ کړم،“ مالِک خُدائ فرمائى. ”زۀ به هر يو خپل ګاونډى ته او خپل بادشاه ته حواله کړم. هغوئ به په مُلک ظلم وکړى، او زۀ به دوئ د هغوئ د لاسونو نه بچ نۀ کړم.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah11_verse_6.mp3', '', 1761754199, 1761754199),
(37892, 'Zechariah 11:7', 'Zechariah', 11, 7, 'نو ما د هغه ګډو شپونتوب وکړو چې د حلالولو دپاره نښه کړے شوى دى، په خاص طور مظلومې ګډې. بيا ما دوه چوکې واخستې چې يوه ”فضل“ او بله ”اتفاق“ بلل کېده، او ما پرې د ګډو شپونتوب وکړو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah11_verse_7.mp3', '', 1761754199, 1761754199),
(37893, 'Zechariah 11:8', 'Zechariah', 11, 8, 'په يوه مياشت کښې ما د قوم د درې شپونکو نه ځان خلاص کړو. خو ګډو ما نه نفرت وکړو، او زۀ د هغوئ نه تنګ شوم', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah11_verse_8.mp3', '', 1761754199, 1761754199),
(37894, 'Zechariah 11:9', 'Zechariah', 11, 9, 'او ومې وئيل، ”زۀ به نور ستاسو شپون نۀ يم. پرېږدئ چې کومې مرى هغه دې مړې شى، او چې کومې تباه کيږى هغه دې تباه شى. پرېږدئ چې کومې پاتې شى هغه دې د يو بل غوښې وخورى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah11_verse_9.mp3', '', 1761754199, 1761754199),
(37895, 'Zechariah 11:10', 'Zechariah', 11, 10, 'بيا ما خپله امسا واخستله چې نوم يې ”فضل“ وو او ماته مې کړه، او هغه لوظ مې مات کړو چې ما ټولو قومونو سره کړے وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah11_verse_10.mp3', '', 1761754199, 1761754199),
(37896, 'Zechariah 11:11', 'Zechariah', 11, 11, 'دا هم په هغه ورځ مات شو. او د ګډو سوداګرو چا چې ما ته کتل پوهه شول چې دا د مالِک خُدائ کلام دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah11_verse_11.mp3', '', 1761754199, 1761754199),
(37897, 'Zechariah 11:12', 'Zechariah', 11, 12, 'ما هغوئ ته ووئيل، ”کۀ تاسو سوچ کوئ چې دا ښۀ دى، ما ته خپله مزدورى راکړئ، خو کۀ ښۀ نۀ وى، نو ځان سره يې کړئ.“ نو هغوئ ما له دېرش د سپينو زرو سيکې مزدورى راکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah11_verse_12.mp3', '', 1761754199, 1761754199),
(37898, 'Zechariah 11:13', 'Zechariah', 11, 13, 'او مالِک خُدائ ما ته وفرمائيل، ”دا په خزانه کښې ورغورزوه.“ دا اوچت قيمت دے کوم قيمت چې هغوئ زما ولګولو، بيا ما دا دېرش د سپينو زرو سيکې واخستلې او د مالِک خُدائ د کور په خزانه کښې مې وروغورزولې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah11_verse_13.mp3', '', 1761754199, 1761754199),
(37899, 'Zechariah 11:14', 'Zechariah', 11, 14, 'بيا ما خپله دوېمه امسا ماته کړه چې نوم يې ”اتفاقى“ وو، او د يهوداه او د اِسرائيل په مينځ کښې ورورولى مې ماته کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah11_verse_14.mp3', '', 1761754199, 1761754199),
(37900, 'Zechariah 11:15', 'Zechariah', 11, 15, 'بيا مالِک خُدائ ما ته وفرمائيل، ”د کم عقل شپون سامان يو ځل بيا راواخله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah11_verse_15.mp3', '', 1761754199, 1761754199),
(37901, 'Zechariah 11:16', 'Zechariah', 11, 16, 'ځکه چې زۀ يو شپون راولم په دې مُلک چې هغه به د ورک شوو پرواه نۀ کوى، يا به خوارۀ شوى نۀ لټوى، يا به زخمى شوو له شفا نۀ ورکوى، نۀ به صحتمندو له خوراک ورکوى، خو هغه به د څُرب ګډانو غوښه خورى او د دوئ سومونه به وشلوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah11_verse_16.mp3', '', 1761754199, 1761754199),
(37902, 'Zechariah 11:17', 'Zechariah', 11, 17, 'افسوس دې په بې‌کاره شپون وى، چې رمه پرېږدى. تُوره دې د هغۀ لاس او د هغۀ ښۍ سترګه ووهى. د هغۀ لاس دې مکمل اوچ شى، او د هغۀ ښۍ سترګه دې بلکل ړنده شى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah11_verse_17.mp3', '', 1761754199, 1761754199),
(37903, 'Ezekiel 11:1', 'Ezekiel', 11, 1, 'د خدای روح زه راپورته کړم او د څښتن د کور ختیځې دروازې ته یې بوتلم. هلته مې دروازې ته نژدې پنځه ویشت سړي ولیدل چې په هغو کې د قوم دوه مشران یعنې د عزور زوی یازنیا او د بنایاه زوی فلتیا هم شامل وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel11_verse_1.mp3', '', 1761754199, 1761754199),
(37904, 'Ezekiel 11:2', 'Ezekiel', 11, 2, 'څښتن ماته وویل: «ای فاني انسانه، دا خلک بد پلانونه جوړوي او په ښار کې خلکو ته بدې مشورې ورکوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel11_verse_2.mp3', '', 1761754199, 1761754199),
(37905, 'Ezekiel 11:3', 'Ezekiel', 11, 3, 'هغوی وایي: ‹مونږ به زر بیا کورونه جوړ کړو. دا ښار د دېګي په شان دی چې په اور باندې ایښی وي او مونږ لکه د غوښې په شان یو، خو لږ تر لږه هغه دېګ مونږ په اور کې د سوځېدلو څخه ساتي.›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel11_verse_3.mp3', '', 1761754199, 1761754199),
(37906, 'Ezekiel 11:4', 'Ezekiel', 11, 4, 'نو ای فاني انسانه، د هغوی په ضد نبوت وکړه! د هغوی په ضد پېشګویي وکړه!»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel11_verse_4.mp3', '', 1761754199, 1761754199),
(37907, 'Ezekiel 11:5', 'Ezekiel', 11, 5, 'بیا په ما باندې د څښتن روح نازل شو او څښتن ماته وویل چې زه داسې وایم: «ای د اسراییلو خلکو، زه پوهېږم چې ستاسو په ذهن کې کوم خیالونه دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel11_verse_5.mp3', '', 1761754199, 1761754199),
(37908, 'Ezekiel 11:6', 'Ezekiel', 11, 6, 'تاسو په ښار کې دومره زیات خلک وژلي دي چې کوڅې د مړو نه ډکې دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel11_verse_6.mp3', '', 1761754199, 1761754199),
(37909, 'Ezekiel 11:7', 'Ezekiel', 11, 7, 'نو زه څښتن تعالی تاسو ته داسې وایم چې دا ښار په رښتیا هم د اوسپنې یو دېګی دی، خو غوښه یې د هغو خلکو ده چې تاسو وژلي دي! نو زه به تاسو د ښار څخه دباندې وباسم!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel11_verse_7.mp3', '', 1761754199, 1761754199),
(37910, 'Ezekiel 11:8', 'Ezekiel', 11, 8, 'زه داسې هم وایم چې تاسو د جنګ څخه وېرېږئ، خو زه به ستاسو دښمنان پرېږدم چې په تاسو باندې حمله وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel11_verse_8.mp3', '', 1761754199, 1761754199);